#!/usr/bin/env python3
"""EZ CRM — чтение данных и отправка команд для Hermes.

Только стандартная библиотека Python 3.9+. Настройка — переменные окружения:
  EZ_GH_OWNER     владелец репозиториев на GitHub
  EZ_DATA_REPO    приватный репозиторий с данными (state.json)
  EZ_DATA_TOKEN   токен GitHub ТОЛЬКО НА ЧТЕНИЕ репозитория данных
  EZ_INBOX_REPO   приватный репозиторий-ящик для команд
  EZ_INBOX_TOKEN  токен GitHub на запись ТОЛЬКО в ящик
  EZ_TZ           часовой пояс хозяина (по умолчанию Europe/Moscow)
  EZ_SKILL_URL    откуда брать обновления навыка (по умолчанию https://crm.belyh-onset.com/hermes)

Навык обновляется сам: раз в сутки — и сразу, как только в данных появилась новая
версия приложения (поле hermesSkill), — скрипт сверяет свою версию с сайтом приложения
и, если там новее, подтягивает файлы навыка (ключи в ~/.hermes/.env не трогает).
Обновиться сразу: `ezcrm.py update`.
Для проверки без сети:
  EZ_STATE_FILE   читать state.json с диска
  EZ_INBOX_DIR    класть команды в папку на диске
  EZ_TODAY        подменить «сегодня» (ГГГГ-ММ-ДД)
"""
import base64, datetime, hashlib, json, os, random, re, string, sys, time, urllib.error, urllib.request

E = os.environ
API = 'https://api.github.com'
MONTHS = ['янв', 'фев', 'мар', 'апр', 'мая', 'июн', 'июл', 'авг', 'сен', 'окт', 'ноя', 'дек']
STEPS = ['Освоение', 'Смета', 'Команда', 'Факт. смета', 'Счёт', 'Оплата', 'Чек']
TIME = re.compile(r'^\d{2}:\d{2}$')
SECTIONS = ['Свет', 'Грип', 'Электрика', 'Спецэффекты', 'Оборудование', 'Логистика', 'Расходники', 'Услуги']
DATE = re.compile(r'^\d{4}-\d{2}-\d{2}$')


def die(msg, code=1):
    print(msg)
    sys.exit(code)


# ---------- самообновление навыка ----------
# Приложение и навык меняются вместе: сборка сайта кладёт свежий навык в hermes/skill.json,
# а версия (отпечаток файлов) лежит рядом в hermes/version.txt. Скрипт сверяет её раз в сутки,
# а после выкладки — сразу: обновлённое приложение пишет версию навыка в данные (hermesSkill),
# и скрипт видит её в state.json, который и так читает. Отдельных опросов в фоне нет.
SKILL_URL = E.get('EZ_SKILL_URL', 'https://crm.belyh-onset.com/hermes').rstrip('/')
SKILL_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SKILL_FILES = re.compile(r'^(SKILL\.md|CHANGELOG\.md|references/[\w.-]+\.md|examples/[\w.-]+\.md|scripts/[\w.-]+\.py)$')


def skill_version():
    try:
        with open(os.path.join(SKILL_DIR, 'VERSION'), encoding='utf-8') as fh:
            return fh.read().strip()
    except OSError:
        return ''


def http_get(url, timeout):
    req = urllib.request.Request(url, headers={'User-Agent': 'ez-crm-hermes', 'Cache-Control': 'no-cache'})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return r.read().decode('utf-8')


def bundle_version(files):
    h = hashlib.sha256()
    for path in sorted(files):
        h.update(path.encode('utf-8') + b'\0' + files[path].encode('utf-8') + b'\0')
    return h.hexdigest()[:12]


def self_update(force=False, every=86400):
    """True — файлы навыка обновлены. Сеть или сайт недоступны — молча работаем с тем, что есть.
    every — не чаще, чем раз в столько секунд (по умолчанию сутки)."""
    mark = os.path.join(SKILL_DIR, '.update-check')
    if not force:
        if E.get('EZ_NO_UPDATE'):
            return False
        try:
            if time.time() - os.path.getmtime(mark) < every:
                return False
        except OSError:
            pass
    try:
        with open(mark, 'w'):
            pass
    except OSError:
        pass
    old = skill_version()
    try:
        remote = http_get(SKILL_URL + '/version.txt', 8).strip()
    except Exception as e:
        if force:
            print(f'Не достучался до {SKILL_URL}: {e}')
        return False
    if not remote or (remote == old and not force):
        return False
    try:
        b = json.loads(http_get(SKILL_URL + '/skill.json', 30))
    except Exception as e:
        print(f'Навык не обновлён — пакет не скачался: {e}')
        return False
    files = b.get('files') or {}
    if not files or bundle_version(files) != b.get('version'):
        print('Навык не обновлён — пакет пришёл битым (отпечаток не сошёлся).')
        return False
    extra = [p for p in files if not SKILL_FILES.match(p)]
    if extra:
        print('Навык не обновлён — в пакете лишние файлы: ' + ', '.join(extra))
        return False
    if b['version'] == old:
        return False
    changed = []
    for path, text in files.items():
        try:
            with open(os.path.join(SKILL_DIR, *path.split('/')), encoding='utf-8') as fh:
                same = fh.read() == text
        except OSError:
            same = False
        if not same:
            changed.append(path)
    try:
        for path, text in files.items():
            dst = os.path.join(SKILL_DIR, *path.split('/'))
            os.makedirs(os.path.dirname(dst), exist_ok=True)
            with open(dst + '.new', 'w', encoding='utf-8') as fh:
                fh.write(text)
            os.replace(dst + '.new', dst)
        with open(os.path.join(SKILL_DIR, 'VERSION'), 'w', encoding='utf-8') as fh:
            fh.write(b['version'])
    except OSError as e:
        print(f'Навык не обновлён — не смог записать файлы: {e}')
        return False
    docs = [p for p in sorted(changed) if p.endswith('.md') and p != 'CHANGELOG.md']
    print(f"⟳ Навык EZ CRM обновлён: {old or 'прежняя версия'} → {b['version']}.")
    if docs:
        print('Перечитай только изменившееся, прежде чем отправлять команды: ' + ', '.join(docs))
    else:
        print('Инструкции не менялись — перечитывать ничего не нужно.')
    if b.get('news'):
        print('Что нового:\n' + b['news'])
    print('—' * 24)
    return True


# ---------- время и формат ----------
def tzinfo():
    try:
        from zoneinfo import ZoneInfo
        return ZoneInfo(E.get('EZ_TZ', 'Europe/Moscow'))
    except Exception:
        return datetime.timezone(datetime.timedelta(hours=3))


def now():
    return datetime.datetime.now(tzinfo())


def today():
    return datetime.date.fromisoformat(E['EZ_TODAY']) if E.get('EZ_TODAY') else now().date()


def money(x):
    return f"{int(round(x or 0)):,}".replace(',', ' ') + ' ₽'


def fdate(iso):
    try:
        d = datetime.date.fromisoformat(str(iso)[:10])
        return f"{d.day} {MONTHS[d.month - 1]}"
    except Exception:
        return iso or '—'


# ---------- GitHub ----------
def gh(method, path, token, body=None, raw=False):
    data = json.dumps(body).encode('utf-8') if body is not None else None
    req = urllib.request.Request(API + path, data=data, method=method)
    req.add_header('Authorization', 'Bearer ' + token)
    req.add_header('Accept', 'application/vnd.github.raw+json' if raw else 'application/vnd.github+json')
    req.add_header('X-GitHub-Api-Version', '2022-11-28')
    req.add_header('User-Agent', 'ez-crm-hermes')
    if data is not None:
        req.add_header('Content-Type', 'application/json')
    try:
        with urllib.request.urlopen(req, timeout=25) as r:
            return r.status, r.read().decode('utf-8')
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode('utf-8', 'replace')
    except urllib.error.URLError as e:
        die(f'Нет связи с GitHub: {e.reason}')


def need(*names):
    miss = [n for n in names if not E.get(n)]
    if miss:
        die('Не заданы переменные окружения: ' + ', '.join(miss))


def load_state():
    if E.get('EZ_STATE_FILE'):
        with open(E['EZ_STATE_FILE'], encoding='utf-8') as fh:
            return after_state(json.load(fh))
    need('EZ_GH_OWNER', 'EZ_DATA_REPO', 'EZ_DATA_TOKEN')
    st, txt = gh('GET', f"/repos/{E['EZ_GH_OWNER']}/{E['EZ_DATA_REPO']}/contents/state.json",
                 E['EZ_DATA_TOKEN'], raw=True)
    if st == 404:
        die('state.json не найден, или у токена нет доступа к репозиторию данных.')
    if st == 401:
        die('Токен EZ_DATA_TOKEN недействителен или истёк.')
    if st != 200:
        die(f'GitHub ответил {st}: {txt[:200]}')
    return after_state(json.loads(txt))


def after_state(st):
    """Приложение уже на новой версии навыка — не ждём суток. Не чаще раза в 5 минут:
    сайт после выкладки обновляется не мгновенно."""
    want = st.get('hermesSkill')
    if want and want != skill_version() and not E.get('EZ_NO_UPDATE') and self_update(every=300):
        sys.stdout.flush()
        os.execve(sys.executable, [sys.executable, os.path.abspath(__file__)] + sys.argv[1:],
                  dict(E, EZ_NO_UPDATE='1'))
    return st


# ---------- модель ----------
def pdates(p):
    return sorted(set(p.get('dates') or ([p['date']] if p.get('date') else [])))


def pdays(p):
    ds = pdates(p)
    if len(ds) > 1 and p.get('days'):
        return sorted(p['days'], key=lambda d: d.get('iso') or '')
    return [{'iso': ds[0] if ds else p.get('date'), 'estimate': p.get('estimate') or [],
             'units': p.get('units') or [], 'notes': p.get('notes') or [],
             'payments': p.get('payments') or []}]


def units_all(p):
    return [u for d in pdays(p) for u in (d.get('units') or [])]


def paid_sum(o):
    return sum((x.get('amount') or 0) for x in (o.get('payments') or []))


def left(o):
    return 0 if o.get('paid') else max(0, (o.get('amount') or 0) - paid_sum(o))


def active(st):
    return [p for p in st.get('projects', []) if not p.get('cancelled')]


def crew_dir(st):
    return {c.get('id'): c for c in st.get('crew', [])}


def is_me(st, pid):
    return bool(crew_dir(st).get(pid, {}).get('me'))


def pname(st, pid):
    c = crew_dir(st).get(pid)
    return (c.get('name') or pid) + (' (я)' if c.get('me') else '') if c else str(pid)


def unit_me(u, idx):
    return bool(u['me']) if u.get('me') is not None else idx == 0


def remaining(p):
    return max(0, (p.get('sum') or 0) - (p.get('paidAmount') or 0))


def settled(p):
    return bool(p.get('paymentDate')) and (p.get('sum') or 0) - (p.get('paidAmount') or 0) <= 0


def income(st, p):
    """Как в приложении: к оплате − выплачено ренталам − выплачено команде − такси."""
    paid_r = sum(paid_sum(r) for r in st.get('rentalDebts', []) if r.get('projectId') == p.get('id'))
    paid_c = sum(paid_sum(c) for u in units_all(p) for c in (u.get('crew') or []))
    taxi = sum((u.get('taxi') or 0) for u in units_all(p))
    return (p.get('sum') or 0) - paid_r - paid_c - taxi


def still_to_pay(st, p):
    """Начислено, но ещё не выплачено ренталам и команде (хозяина не считаем)."""
    due = lambda o: paid_sum(o) if o.get('paid') else (o.get('amount') or 0)
    rs = [r for r in st.get('rentalDebts', []) if r.get('projectId') == p.get('id')]
    cs = [c for u in units_all(p) for c in (u.get('crew') or []) if not is_me(st, c.get('id'))]
    return sum(max(0, due(o) - paid_sum(o)) for o in rs + cs)


def find_project(st, q):
    ps = st.get('projects', [])
    for p in ps:
        if p.get('id') == q:
            return p
    for t in st.get('trash') or []:
        if t.get('pid') == q or (t.get('name') or '').casefold() == q.casefold().strip():
            die(f"Проект «{t.get('name')}» в корзине (id {t.get('pid')}). Вернуть: send project.restore")
    ql = q.casefold().strip()
    exact = [p for p in ps if (p.get('name') or '').casefold() == ql]
    if len(exact) == 1:
        return exact[0]
    part = [p for p in ps if ql in (p.get('name') or '').casefold() or ql in (p.get('client') or '').casefold()]
    if len(part) == 1:
        return part[0]
    if not part:
        die(f'Проект «{q}» не найден. Попробуй: find')
    die(f'Под «{q}» подходит несколько проектов — уточни id:\n' + '\n'.join(
        f"  {p.get('id')} · {p.get('name')} · {', '.join(fdate(d) for d in pdates(p)) or '—'}" for p in part))


def unit_text(st, u, idx):
    parts = []
    if u.get('fixedHours') not in (None, ''):
        parts.append(f"смена {u['fixedHours']} ч (фикс)")
    else:
        if u.get('loadStart'):
            parts.append(f"погрузка {u['loadStart']}")
        if u.get('shiftStart') or u.get('shiftEnd'):
            parts.append(f"смена {u.get('shiftStart') or '?'}–{u.get('shiftEnd') or '?'}")
        if u.get('loadEnd'):
            parts.append(f"разгрузка до {u['loadEnd']}")
    flags = [f for f, on in (('ночная', u.get('night')), ('текущий обед', u.get('lunch')),
                             ('без прогрессивов', u.get('progressive') is False),
                             ('П/Р переработкой', u.get('loadAsOt'))) if on]
    if u.get('gapHours'):
        flags.append(f"разрыв {u['gapHours']} ч")
    if u.get('taxi'):
        flags.append(f"такси {money(u['taxi'])}")
    if unit_me(u, idx):
        flags.append('я на смене')
    crew = ', '.join(f"{pname(st, c.get('id'))} — {c.get('role') or '?'}" for c in (u.get('crew') or []))
    s = f"{u.get('name') or 'Юнит'}: {', '.join(parts) or 'время не указано'}"
    if flags:
        s += ' [' + ', '.join(flags) + ']'
    return s + '\n      команда: ' + (crew or 'никого')


# ---------- команды чтения ----------
def events_on(st, iso):
    out = []
    for p in active(st):
        ds = pdates(p)
        if iso in ds:
            day = next((d for d in pdays(p) if d.get('iso') == iso), None) or (pdays(p)[0] if len(ds) == 1 else None)
            out.append(('съёмка', p, day))
        if p.get('scoutDate') == iso:
            out.append(('освоение', p, None))
        if p.get('expectedPaymentDate') == iso and remaining(p) > 0:
            out.append(('ждём оплату', p, None))
    return out


def print_events(st, iso, label):
    ev = events_on(st, iso)
    print(f"{label} · {fdate(iso)}" + ('' if ev else ': ничего'))
    for kind, p, day in ev:
        extra = f" · {money(remaining(p))}" if kind == 'ждём оплату' else ''
        print(f"  {kind}: {p.get('name')} [{p.get('id')}] · {p.get('location') or '—'}{extra}")
        if day:
            for i, u in enumerate(day.get('units') or []):
                print('    ' + unit_text(st, u, i))


def cmd_today(st, a):
    t = today()
    print_events(st, t.isoformat(), 'Сегодня')
    print_events(st, (t + datetime.timedelta(days=1)).isoformat(), 'Завтра')
    open_tasks = [x for x in st.get('customTasks', []) if not x.get('done')]
    if open_tasks:
        print(f"Открытых задач: {len(open_tasks)}")
        for x in open_tasks[:5]:
            print(f"  [{x.get('id')}] {x.get('text')}")


def cmd_upcoming(st, a):
    n = int(a[0]) if a else 14
    t = today()
    found = False
    for i in range(n):
        iso = (t + datetime.timedelta(days=i)).isoformat()
        if events_on(st, iso):
            found = True
            print_events(st, iso, 'День')
    if not found:
        print(f'За {n} дн. ничего не запланировано.')


def cmd_project(st, a):
    if not a:
        die('Нужно: project <id или название>')
    p = find_project(st, ' '.join(a))
    print(f"{p.get('name')} · id {p.get('id')}")
    print(f"Клиент: {p.get('client') or '—'} · место: {p.get('location') or '—'}")
    print(f"Дни: {', '.join(fdate(d) for d in pdates(p)) or '—'}"
          + (f" · освоение {fdate(p['scoutDate'])}" if p.get('scoutDate') else ''))
    crewline = ' · '.join(f"{k} {p.get(f) or '—'}" for k, f in
                          (('продюсер', 'producer'), ('оператор', 'operator'), ('режиссёр', 'director')))
    print(crewline)
    steps = p.get('steps') or []
    print('Чекпойнты: ' + '  '.join(('✓ ' if s[1] else '· ') + s[0] for s in steps if len(s) > 1))
    line = f"Деньги: к оплате {money(p.get('sum'))} · получено {money(p.get('paidAmount'))} · осталось {money(remaining(p))}"
    if p.get('expectedPaymentDate') and remaining(p) > 0:
        line += f" · обещали {fdate(p['expectedPaymentDate'])}"
    print(line + (' · счёт выставлен' if p.get('invoiceSent') else ''))
    stp = still_to_pay(st, p)
    print(f"Мой доход по проекту: {money(income(st, p))} (к оплате − выплачено ренталам и команде − такси)"
          + (f" · из них ещё предстоит выплатить {money(stp)}" if stp > 0 else ''))
    if p.get('cancelled'):
        print(f"ОТМЕНЁН {fdate((p.get('cancelInfo') or {}).get('at'))}")
    if p.get('trip'):
        td = p.get('tripData') or {}
        print(f"Командировка: {'с командой' if td.get('mode') == 'crew' else 'еду один'}")
    for d in pdays(p):
        print(f"— {fdate(d.get('iso'))} —")
        for i, u in enumerate(d.get('units') or []):
            print('  ' + unit_text(st, u, i))
            for c in (u.get('crew') or []):
                if is_me(st, c.get('id')):
                    continue
                state = '✓ закрыто' if c.get('paid') else f"осталось {money(left(c))}"
                print(f"      выплата {pname(st, c.get('id'))}: начислено {money(c.get('amount'))}, "
                      f"выплачено {money(paid_sum(c))}, {state}")
        est = d.get('estimate') or []
        if est:
            tot = sum((x.get('qty') or 0) * (x.get('payDays') or x.get('days') or 0) * (x.get('price') or 0) for x in est)
            print(f"  смета дня: {len(est)} поз. на {money(tot)}")
        for pm in (d.get('payments') or []):
            print(f"  поступление {money(pm.get('amount'))} · {'наличные' if pm.get('type') == 'cash' else 'безнал'} · {fdate(pm.get('date'))}")
        for n in (d.get('notes') or [])[-3:]:
            print(f"  заметка: {n.get('text')}")
    for r in st.get('rentalDebts', []):
        if r.get('projectId') == p.get('id'):
            state = '✓ закрыто' if r.get('paid') else f"осталось {money(left(r))}"
            print(f"Рентал {r.get('rental')}: начислено {money(r.get('amount'))}, выплачено {money(paid_sum(r))}, {state}")


def cmd_find(st, a):
    if not a:
        die('Нужно: find <текст>')
    q = ' '.join(a).casefold()
    hits = 0
    for p in st.get('projects', []):
        hay = ' '.join(str(p.get(k) or '') for k in ('id', 'name', 'client', 'location')).casefold()
        if q in hay:
            hits += 1
            mark = ' (отменён)' if p.get('cancelled') else ''
            print(f"проект  {p.get('id')} · {p.get('name')} · {', '.join(fdate(d) for d in pdates(p)) or '—'}{mark}")
    for t in st.get('trash') or []:
        if q in ' '.join(str(t.get(k) or '') for k in ('pid', 'name')).casefold():
            hits += 1
            print(f"проект  {t.get('pid')} · {t.get('name')} (в корзине — вернуть: project.restore)")
    for c in st.get('crew', []):
        if q in (c.get('name') or '').casefold():
            hits += 1
            print(f"человек {c.get('id')} · {c.get('name')}{' (я)' if c.get('me') else ''}")
    for r in st.get('rentals', []):
        if q in str(r).casefold():
            hits += 1
            print(f"рентал  {r}")
    if not hits:
        print('Ничего не найдено.')


def cmd_money(st, a):
    ps = st.get('projects', [])
    mark = lambda p: ' (проект отменён)' if p.get('cancelled') else ''
    print('Клиенты должны:')
    tot = 0
    for p in ps:
        r = remaining(p)
        if p.get('cancelled') and not (p.get('cancelInfo') or {}).get('penalty'):
            continue   # отменён без неустойки — клиент ничего не должен
        if (p.get('sum') or 0) > 0 and r > 0:
            tot += r
            tail = 'счёт выставлен' if p.get('invoiceSent') else 'счёт не выставлен'
            if p.get('expectedPaymentDate'):
                tail += f", обещали {fdate(p['expectedPaymentDate'])}"
            print(f"  {p.get('name')}{' — неустойка' if p.get('cancelled') else ''} — {money(r)} ({tail})")
