                          + ('ДОЛГ: клиент уже заплатил' if real else 'ждём денег клиента'))
    print(f"  долг сейчас: {money(debt)} · ещё не наступило: {money(wait)}")
    print('Ренталам (осталось выплатить):')
    rt = 0
