def validate(op, a):
    errs = [f'нет аргумента «{k}»' for k in OPS[op] if k not in a or a[k] in (None, '')]
    for k in ('loadStart', 'shiftStart', 'shiftEnd', 'loadEnd'):
        if a.get(k) and not TIME.match(str(a[k])):
            errs.append(f'«{k}» должно быть ЧЧ:ММ')
    for k in ('day', 'date'):
        if a.get(k) and not DATE.match(str(a[k])):
            errs.append(f'«{k}» должно быть ГГГГ-ММ-ДД')
    if 'dates' in a and (not isinstance(a['dates'], list) or not all(DATE.match(str(d)) for d in a['dates'])):
        errs.append('«dates» — список дат ГГГГ-ММ-ДД')
    if 'type' in a and a['type'] not in ('cash', 'noncash'):
        errs.append('«type» — cash или noncash')
    if 'amount' in a:
        try:
            if float(a['amount']) <= 0:
                errs.append('«amount» должна быть больше нуля')
        except (TypeError, ValueError):
            errs.append('«amount» — число')
    if op == 'project.step' and a.get('step') not in STEPS:
        errs.append('«step» — один из: ' + ', '.join(STEPS))
    if op == 'personal.debt' and a.get('direction') not in ('owe', 'owed'):
        errs.append('«direction» — owed (мне должны) или owe (я должен)')
    if op == 'estimate.add':
        lines = a.get('lines')
        if not isinstance(lines, list) or not lines:
            errs.append('«lines» — непустой список позиций')
        else:
            for i, ln in enumerate(lines, 1):
                if not isinstance(ln, dict):
                    errs.append(f'позиция {i}: нужен объект {{sec, name, qty, price}}')
                    continue
                errs += [f'позиция {i}: нет «{k}»' for k in ('sec', 'name', 'qty', 'price') if k not in ln]
                if ln.get('sec') and ln['sec'] not in SECTIONS:
                    errs.append(f'позиция {i}: раздел — один из: ' + ', '.join(SECTIONS))
                try:
                    if float(ln.get('qty', 1)) <= 0 or float(ln.get('price', 0)) < 0:
                        errs.append(f'позиция {i}: qty больше нуля, price не меньше нуля')
                except (TypeError, ValueError):
                    errs.append(f'позиция {i}: qty и price — числа')
    if op == 'project.dates' and not a.get('dates'):
        errs.append('«dates» — хотя бы одна дата')
    return errs


def inbox_list(sub):
    d = E.get('EZ_INBOX_DIR')
    if d:
        path = os.path.join(d, sub)
        return sorted(f[:-5] for f in os.listdir(path) if f.endswith('.json')) if os.path.isdir(path) else []
    need('EZ_GH_OWNER', 'EZ_INBOX_REPO', 'EZ_INBOX_TOKEN')
    st, txt = gh('GET', f"/repos/{E['EZ_GH_OWNER']}/{E['EZ_INBOX_REPO']}/contents/{sub}", E['EZ_INBOX_TOKEN'])
    if st == 404:
        return []
    if st != 200:
        die(f'Ящик недоступен — GitHub ответил {st}: {txt[:200]}')
    return sorted(x['name'][:-5] for x in json.loads(txt) if x.get('name', '').endswith('.json'))


def inbox_read(sub, cid):
    d = E.get('EZ_INBOX_DIR')
    if d:
        with open(os.path.join(d, sub, cid + '.json'), encoding='utf-8') as fh:
            return json.load(fh)
    st, txt = gh('GET', f"/repos/{E['EZ_GH_OWNER']}/{E['EZ_INBOX_REPO']}/contents/{sub}/{cid}.json",
                 E['EZ_INBOX_TOKEN'], raw=True)
    return json.loads(txt) if st == 200 else {}


def cmd_send(a):
    if len(a) < 2:
        die('Нужно: send <op> \'<json>\' [--say "фраза"]')
    op = a[0]
    if op not in OPS:
        die(f'Неизвестная операция «{op}». Есть: ' + ', '.join(sorted(OPS)))
    try:
        args = json.loads(a[1])
    except json.JSONDecodeError as e:
        die(f'Аргументы — не JSON: {e}')
    say = a[a.index('--say') + 1] if '--say' in a and a.index('--say') + 1 < len(a) else ''
    errs = validate(op, args)
    if errs:
        die('Команда НЕ отправлена:\n  ' + '\n  '.join(errs))
    n = now()
    # микросекунды в id: команды, отправленные подряд в одну секунду, всё равно
    # выстраиваются строго в порядке отправки — приложение применяет их по id
    cid = n.strftime('%Y%m%d-%H%M%S-%f') + '-' + ''.join(random.choices(string.ascii_lowercase + string.digits, k=4))
    env = {'v': 1, 'id': cid, 'ts': n.isoformat(timespec='seconds'), 'by': 'hermes',
           'op': op, 'args': args, 'say': say}
    body = json.dumps(env, ensure_ascii=False, indent=2)
    d = E.get('EZ_INBOX_DIR')
    if d:
        os.makedirs(os.path.join(d, 'inbox'), exist_ok=True)
        with open(os.path.join(d, 'inbox', cid + '.json'), 'w', encoding='utf-8') as fh:
            fh.write(body)
    else:
        need('EZ_GH_OWNER', 'EZ_INBOX_REPO', 'EZ_INBOX_TOKEN')
        st, txt = gh('PUT', f"/repos/{E['EZ_GH_OWNER']}/{E['EZ_INBOX_REPO']}/contents/inbox/{cid}.json",
                     E['EZ_INBOX_TOKEN'],
                     {'message': f'hermes: {op}', 'content': base64.b64encode(body.encode('utf-8')).decode('ascii')})
        if st not in (200, 201):
            die(f'Команда НЕ отправлена — GitHub ответил {st}: {txt[:200]}')
    print(f'В очереди: {op} · id {cid}')


def cmd_queue(a):
    inbox, done = inbox_list('inbox'), set(inbox_list('done'))
    pending = [c for c in inbox if c not in done]
    print(f'Ждут применения: {len(pending)}')
    for cid in pending[-20:]:
        env = inbox_read('inbox', cid)
        print(f"  {cid} · {env.get('op')} · {env.get('say') or json.dumps(env.get('args'), ensure_ascii=False)[:80]}")
    failed = [r for r in (inbox_read('done', c) for c in sorted(done)[-20:]) if r.get('status') == 'failed']
    if failed:
        print('Упали (последние):')
        for r in failed[-5:]:
            print(f"  {r.get('id')} · {r.get('error')}")


def cmd_status(a):
    if not a:
        die('Нужно: status <id команды>')
    cid = a[0]
    if cid not in inbox_list('inbox'):
        die(f'Команды {cid} в ящике нет.')
    if cid not in set(inbox_list('done')):
        print(f'{cid}: ещё не применена — приложение внесёт при открытии.')
        return
    r = inbox_read('done', cid)
    st = r.get('status')
    if st == 'applied':
        print(f"{cid}: внесено — {r.get('summary') or 'без подробностей'}")
    elif st == 'failed':
        print(f"{cid}: НЕ внесено — {r.get('error') or 'без причины'}")
    else:
        print(f"{cid}: вносится на устройстве «{r.get('device') or '?'}» — проверь чуть позже.")


