def main():
    extra = ['send', 'queue', 'status', 'update']
    if len(sys.argv) < 2 or sys.argv[1] in ('-h', '--help', 'help'):
        die(__doc__ + '\nКоманды: ' + ', '.join(list(READERS) + extra), 0)
    cmd, rest = sys.argv[1], sys.argv[2:]
    if cmd == 'update':
        if not self_update(force=True):
            print(f'Навык EZ CRM: версия {skill_version() or "неизвестна"}')
        return
    # раз в сутки сверяемся с сайтом; навык обновился — перезапускаемся уже новым кодом,
    # чтобы команда шла по новым правилам
    if self_update():
        sys.stdout.flush()
        os.execve(sys.executable, [sys.executable, os.path.abspath(__file__)] + sys.argv[1:],
                  dict(E, EZ_NO_UPDATE='1'))
    if cmd == 'send':
        return cmd_send(rest)
    if cmd == 'queue':
        return cmd_queue(rest)
    if cmd == 'status':
        return cmd_status(rest)
    if cmd not in READERS:
        die(f'Неизвестная команда «{cmd}». Есть: ' + ', '.join(list(READERS) + extra))
    READERS[cmd](load_state(), rest)


if __name__ == '__main__':
    main()
